changeSet.sql:
CREATE TRIGGER message_au AFTER UPDATE ON message BEGIN
    INSERT INTO message_fts(message_fts, rowid, message_id, content, properties)
    VALUES ('delete', old.rowid, old.message_id, old.content, old.properties);
    INSERT INTO message_fts(rowid, message_id, content, properties)
    VALUES (new.rowid, new.message_id, new.content, new.properties);
END
